// Code generated by porting packages/cli/src/help.ts (data port, see docs/scope-go-cli.md §4).
//
// parlay CLI usage and per-command help text.
package help

import (
	"fmt"
	"strings"

	"github.com/trillium/parlay/tools/cli/internal/config"
)

// usageTemplate is USAGE with the live server URL replaced by a {{SERVER}} placeholder —
// Go has no import-time SERVER snapshot, so Usage(server) substitutes it per call.
const usageTemplate = "parlay — talk to a Parlay chat server (current target: {{SERVER}})\n\nUsage:\n  parlay                          Panel/fleet snapshot: subscribers, agents, last 3 messages\n  parlay status <verb> [--key <slug>] <note...>   Emit a keyed agent→supervisor status line (fold §3.6)\n  parlay status                   Read THIS agent's keyed status file\n  parlay subscribers [--full]     Connection counts (--full: raw JSON)\n  parlay agents [--full]          List registered agents (--full: raw JSON)\n  parlay agent-down <id>          Deregister any agent channel (general-purpose; not just variants)\n  parlay remote                   Show the current server URL + its source (env/config/default)\n  parlay remote set <url>         Persist a default server URL (~/.parlay/config.json; survives shells)\n  parlay remote clear             Remove the persisted default server URL\n  parlay nickname <nick...>       Set voice nicknames for THIS agent (picker/voice channel-switch)\n  parlay nickname --agent <id> <nick...>   Set nicknames for a named agent (--clear to remove)\n  parlay send                     List agents you can message\n  parlay send --<agent-id> <text> Send attributed message to that agent's channel\n  parlay say <text...>            Reply to YOUR OWN channel (spawned agents; identity from PARLAY_AGENT_ID)\n  parlay reply <text...>          Alias for 'say' (bare 'reply' wraps this)\n  parlay scratchpad [<note>]      Your durable task notes; no args = read (bare 'scratchpad' wraps this)\n  parlay identity [<fact>]        Your durable self-knowledge; no args = read (bare 'identity' wraps this)\n  parlay alert <text...>          Broadcast an alert to all pollers + agents\n  parlay alert --agent <id> <text...>   Alert one agent channel\n  parlay history [N] [--full]     Last N messages, truncated (default 20; --full: untruncated)\n  parlay monitor --agent <id> [--notify-safe]   Relay-backed enroll + stream — emits CHAT_MSG lines (for Monitor{})\n  parlay monitor --legacy-poll [--agent <id>]   Old independent poll loop (no relay)\n  parlay listen --agent <id> [--name <name>] [--caps <json>] [--notify-safe]   One-call self-enroll: register + announce + monitor (alias: agent-up)\n  parlay stats                    Message memory/complexity stats (count, sizes, ages, images)\n  parlay health                   Server vitals: relay, memory, pulse wrapper, eval-engine\n  parlay doctor                   THIS agent's self-diagnosis: PASS/WARN/FAIL + fix per check\n  parlay context-check <pct>      Rotation advisory: OK, or ROTATE (exit 3) at/above the threshold (default 85%)\n  parlay robots-watch [--once]    Event poll-daemon: robots-created→mechanic-dispatch, request-closed→notify\n  parlay robots-tail [--once]     Push fast-path: tail robots events.jsonl → mechanic-dispatch (~1s, poll stays fallback)\n  parlay mechanic off|on|status   Pause / resume auto-mechanic dispatch (kill switch for robots→mechanic spawner)\n  parlay launch                   List all known agents + live status (from ~/.parlay/agents/)\n  parlay launch <id>              Spawn an offline agent via parlay-spawn (uses identity frontmatter)\n  parlay spawn <id> <name> <color> [<prompt>] [flags]   Spawn a new agent via parlay-spawn\n  parlay claim <task-id>          One-call agent bootstrap: profile + enroll + the task, from a ticket (idea-tm0)\n  parlay merge-gate <pr>          Is this PR ACTUALLY safe to merge? (catches green-but-vacuous checks)\n  parlay landed <pr>              Did the fix ACTUALLY land? MERGED in THIS repo + commit on the remote base\n  parlay branch-audit [<branch>]  What does this branch REALLY change? (merge-base truth; behind != reverted)\n  parlay commands [--all] [--watch] [--json]   What is parlay running right NOW (live-command registry)\n  parlay variant launch <id>      Fork a live agent into an isolated git-worktree variant\n  parlay variant list [<id>]      List variants (optionally filtered to one primary)\n  parlay variant merge <id>       Merge variant's insights back into primary (idempotent)\n  parlay variant teardown <id>    Merge + remove worktree + unregister variant\n  parlay crew-state <id>          Read an agent's current state (reconcile status vs oracle)\n  parlay supervise <id>           Wake-on-actionable-status loop with absorb-when-working logic\n  parlay teardown <id> [--force]  Safe destroy of an agent with worktree (refuses unlanded work)\n  parlay sweep [--apply]          Fleet closure sweep: close every done agent, surface the rest\n  parlay sweep --agent <id>       Sweep one agent by id (skips the per-task-spawn proof)\n  parlay stale <agent-id>         Is this pane worth sending to? FRESH (0) or STALE — relaunch (exit 3)\n  parlay guard [--repo P]         Runtime worktree-tangle + watcher-liveness alarm (advisory; never blocks)\n  parlay guard --beat             Touch the liveness beacon (watcher heartbeat, per poll cycle)\n  parlay lavish-import            Import lavish sessions\n  parlay help                     Show this help\n\nAny subcommand accepts --help. Exit codes: 0 ok, 1 server/runtime error, 2 usage error.\n\nEnv:\n  PARLAY_SERVER   Server base URL override (highest precedence; wins over persisted config and the coded default)\n\nServer URL resolution (highest wins): PARLAY_SERVER env var > ~/.parlay/config.json (\"server\" key,\n  set via 'parlay remote set <url>') > coded default http://localhost:4242. See 'parlay remote --help'.\n"

// Usage renders the full USAGE text with the given server URL substituted in.
func Usage(server string) string {
	return strings.Replace(usageTemplate, "{{SERVER}}", server, 1)
}

// HELP is the per-command help text map, keyed by subcommand name.
var HELP = map[string]string{
	"status":        "parlay status — the fold's agent→supervisor keyed status verb (§3.6). Ports firstmate's grammar '<verb> [key=<slug>]: <note>'.\nUsage: parlay status <verb> [--key <slug>] <note...>   append a keyed status line\n       parlay status                                   read THIS agent's status file\n  Verbs: working, needs-decision, blocked, paused, done, failed, resolved.\n  Sink: $PARLAY_STATUS_FILE when set (firstmate injects it at spawn; its fm-watch loop reads it),\n        else ~/.parlay/agents/<id>/status keyed by PARLAY_AGENT_ID. Same verb, two homes.\n  --key <slug>  open/close a durable keyed decision (slug chars [A-Za-z0-9._-]); a bare needs-decision\n                uses key 'default', and 'resolved [--key <slug>]' closes the matching open decision.\nNOTE: 'status' was formerly a redundant alias of bare 'parlay'. The panel/fleet snapshot now lives ONLY\n      on bare 'parlay'; this name was repurposed for the fold verb (task-ve2v resolves the C1 collision).",
	"subscribers":   "parlay subscribers — connection counts (panel clients, pollers, registered agents).\nUsage: parlay subscribers [--full]\n  --full   Print the raw JSON from /api/chat/subscribers",
	"agents":        "parlay agents — registered agents, one per line (id, name, color).\nUsage: parlay agents [--full]\n  --full   Print the raw JSON from /api/chat/agents",
	"agent-down":    "parlay agent-down — deregister any agent channel from the registry.\nUsage: parlay agent-down <id>\nGeneral-purpose counterpart to 'variant teardown' (which only unregisters git-worktree variants):\nany spawner (e.g. a firstmate crewmate) can call this on clean shutdown to remove its channel.\nPOSTs to /api/chat/unregister. Fails LOUD (non-zero exit, server's error message) on an unknown\nor already-gone id — never a silent success. On success prints a short confirmation.",
	"remote":        "parlay remote — persist a default server URL so a non-default Pulse/relay target (e.g. a\nTailscale-networked host like 'mini1' talking to a relay on 'macbook:31337') survives across shells\nwithout re-exporting PARLAY_SERVER every session.\nUsage: parlay remote                  → print the current server URL + its source (env/config/default)\n       parlay remote set <url>       → persist <url> to ~/.parlay/config.json (\"server\" key)\n       parlay remote clear           → remove the persisted value (falls back to env/default)\nResolution precedence (highest wins): PARLAY_SERVER env var > persisted config > coded default\nhttp://localhost:4242. The env var always overrides — 'remote set' only changes the fallback used\nwhen PARLAY_SERVER is unset. State dir honors $PARLAY_STATE_HOME (default ~/.parlay), same as guard\nand robots-watch. Check which source is active with 'parlay doctor' or 'parlay remote'.",
	"nickname":      "parlay nickname — assign voice nicknames so the channel picker + voice channel-switch resolve an agent by an easy spoken word.\nUsage: parlay nickname <nick> [<nick2> …]        set nicknames for THIS agent (PARLAY_AGENT_ID)\n       parlay nickname --agent <id> <nick> …     set nicknames for a named agent\n       parlay nickname --agent <id> --clear      remove all nicknames\nThe FIRST nickname becomes the picker's display label for that channel. Metadata-only\nupsert via /api/chat/register-agent — does not post a message. Re-running replaces the set.",
	"send":          "parlay send — list or message another agent's channel (all messages visible to the human).\nUsage: parlay send                          → list agents you can message\n       parlay send --agent <id> \"text\"     → send attributed message to that agent's channel\n       parlay send --<agent-id> \"text\"     → same thing, shorthand form\nExamples:\n  send                          # prints: send --mayor, send --shepherd, …\n  send --agent mayor \"heads up\" # lands on mayor's channel; human sees it too\n  send --mayor \"heads up\"       # shorthand for the same send\n  send --shepherd \"done\"        # attributed to PARLAY_AGENT_ID (auto-filled)\n  --agent <id> | --to <id>      # explicit target (matches 'parlay listen --agent <id>')\n  --from <id>                   # override sender attribution (rarely needed)\n  --force                       # skip BOTH pre-flight checks below (seed a channel; wake a done pane)\nTwo pre-flight checks, both refusing with a non-zero exit and both failing OPEN:\n  1. REGISTERED? The target is checked against the live registry — an unregistered id is refused\n     rather than accepted onto a channel nothing polls (robots-ngg5: a send that returns a message\n     id but is never delivered gives the caller no signal to retry). An unreadable registry warns\n     on stderr and proceeds.\n  2. WORTH SENDING TO? A target that finished its task and is sitting at its prompt is a STALE\n     WINDOW — continuing it makes the new work re-pay for the whole finished session on every turn\n     (robots-9d2w). Refused with the relaunch commands; see 'parlay stale --help' for the policy.\n     Unknown state is never stale, so a relay hiccup can't become a refused send. --force waives it,\n     which is the right call for a follow-up question ABOUT the work the agent just finished.\nAll messages land on the target's SHARED human channel — no private side channels.\nThe receiving agent's monitor emits: CHAT_MSG|id|role|text|from:<sender>",
	"say":           "parlay say — reply to your OWN Parlay channel with no boilerplate (for agents spawned by parlay-spawn).\nUsage: parlay say <text...>   |   echo \"long reply\" | parlay say\n  Identity comes from PARLAY_AGENT_ID (set at spawn); override with --agent <id>.\n  The server keeps your registered name/color, so you only supply the text.\n  Alias: parlay reply. Dead-simple wrapper on PATH: reply \"<text>\".\n  Shutdown guard: if you post while an OPEN handoff is not yet submitted, a loud stderr\n  warning steers you to 'identity --submit' — chat here is the create→submit death window.\n  The send still goes through; the warning never blocks it.",
	"scratchpad":    "parlay scratchpad — your durable task notes, keyed by PARLAY_AGENT_ID (survives restarts).\nUsage: scratchpad '<note>'   append   |   scratchpad   read   |   scratchpad --clear | --path\n  Also: --agent <id>, and stdin (echo 'note' | scratchpad). Store: ~/.parlay/agents/<id>/scratchpad.md",
	"identity":      "parlay identity — your durable self-knowledge (traits, failure modes, lessons), keyed by PARLAY_AGENT_ID.\nUsage: identity '<fact>'   add   |   identity   read   |   identity --clear | --path\n  identity --handoff [<handoff-id>]         pin a pointer to your handoff bead (pin only — does not restart).\n  identity --dismiss-handoff [<handoff-id>] NON-DESTRUCTIVE dismiss of an inherited stale handoff. Pins the pointer\n                                             (same as --handoff) but prints a \"dismissed, context NOT reset\" message.\n                                             Use when a fresh context reusing an agent-id sees a prior session's stale\n                                             open handoff and gets nagged. Does NOT trigger a context reset.\n  identity --submit [<handoff-id>]          PERSISTENT agent: pin it AND reset your context — ENDS the session and relaunches you with a\n                                     fresh context that recovers via identity -> handoff -> scratchpad. Add --dry to preview.\n  The handoff id is OPTIONAL: omit it and your NEWEST OPEN handoff is resolved from the store (agent-scoped), so\n                                     'handoff create … && identity --submit' is ONE atomic act — no room for an interposed\n                                     step to strand your shutdown, and a bare submit recovers a create that already landed.\n  ATOMIC CONTRACT: create then submit with NOTHING between. Post no chat in that window — 'parlay say'/'reply' will\n                                     warn you if you do. The pin is set at CREATE time, so recovery survives a missed submit.\n  identity --park [<handoff-id>]            PAUSE: pin the handoff AND shut down WITHOUT restarting — the session ENDS and does\n                                     NOT relaunch. The bound bead is left OPEN, which is the signal that work remains; a\n                                     future spawn (manual or mechanic-dispatch) resumes it, recovering via identity ->\n                                     handoff -> scratchpad. Same optional-id + atomic contract as --submit. Add --dry to preview.\n  identity --complete <store-item>  SINGLE-USE agent: close the work item you finished (e.g. task-abc → 'task close') and\n                                     END for good — no restart. The counterpart to --submit. Add --dry to preview.\n  Three-exit model: bead OPEN + continue now → --submit (restart); bead OPEN + pause → --park (stop, resume later);\n                                     bead CLOSED + done → --complete (terminate). All three are the whole shutdown — no separate\n                                     sudoku/context-reset step.\n  identity --rename <old-id> --to <new-id> [--name N] [--color C] [--cwd P] [--model M] [--preserve]\n                                     Move an agent's store to a new id and re-register with the server. Guards against\n                                     clobbering an existing <new-id>. --preserve drops the ephemeral marker (adopt an\n                                     ephemeral into a durable identity). Does NOT relaunch — relaunch with 'identity --launch <new-id>'.\n  identity --reap-ephemeral [--older-than <hours>h] [--dry]\n                                     GC ephemeral (hash-identity) agents whose identity.md is idle past the window\n                                     (default 24h). --dry previews without deleting.\n  Also: --agent <id>, and stdin. Read identity on every startup to recover yourself. Store: ~/.parlay/agents/<id>/identity.md",
	"alert":         "parlay alert — broadcast an alert to pollers + agents.\nUsage: parlay alert [--agent <id>] <text...>\n  --agent <id>   Deliver only to one agent channel",
	"history":       "parlay history — print recent messages (server-bounded).\nUsage: parlay history [N] [--full]\n  N        How many messages (default 20)\n  --full   Untruncated text plus id and channel per message",
	"monitor":       "parlay monitor — enroll with the relay and stream CHAT_MSG|id|role|text lines on stdout.\nUsage: parlay monitor --agent <id> [--notify-safe] [--legacy-poll]\n  --agent <id>    Agent channel to enroll + stream (required unless --legacy-poll)\n  --notify-safe   Cap each emitted line to a notification-safe budget (PARLAY_NOTIFY_BUDGET,\n                  default 400) and append a \"fetch full text\" pointer. Use this when running\n                  under a harness Monitor tool: harness notifications truncate long lines\n                  mid-word silently, so a long voice-dictated message reaches the agent cut off\n                  with no signal. --notify-safe makes the cut deterministic, self-describing, and\n                  recoverable (the message id survives; 'parlay history --full' fetches the rest).\n                  Default off so raw programmatic consumers still get complete, unmodified lines.\n  --legacy-poll   Use the old independent poll loop with no relay (global feed if no --agent)\n\nDefault path registers <id> with the central relay (tools/relay/parlay-relay must\nbe running) and execs 'tail -F' on the agent's spool — ~1.2MB per agent, one relay\nfans out to all. See tools/RELAY_MONITOR.md.",
	"listen":        "parlay listen — one-call agent self-enrollment (alias: agent-up). Atomically:\n  1. Registers <id> in the server's agent registry (POST /api/chat/register-agent) — identity + optional --caps.\n  2. Announces \"listening\" on the agent's own channel (POST /api/chat/reply).\n  3. execs into the SAME poll loop as 'parlay monitor --agent <id>' — reused, not duplicated.\nUsage: parlay listen --agent <id> [--name <name>] [--color <hex>] [--caps <json>] [--notify-safe] [--legacy-poll]\n  --agent <id>    Required. Kebab-slug agent id.\n  --name <name>   Display name (default: <id>).\n  --color <hex>   Tab accent color (default: deterministic from <id>, same as ephemeral identities).\n  --caps <json>   Optional capabilities payload forwarded on registration.\n  --notify-safe   Forwarded to the underlying monitor: cap each emitted line to a notification-safe\n                  budget (PARLAY_NOTIFY_BUDGET, default 400) so a long captain message can't blow the\n                  agent's context on delivery under a harness Monitor. See 'parlay monitor --help'.\n  --legacy-poll   Forwarded to the underlying monitor (no relay).\nArming is a TAKEOVER (robots-fgyz): before step 1, any OTHER live poll loop on this agent's channel\nis ended (SIGTERM, then SIGKILL for a survivor), announced on stderr, so the channel keeps exactly one\nreader. Without it every restart/reconnect/turn added a loop and each message was processed once per\nloop — the Mayor agent reached 12. Set PARLAY_LISTEN_NO_SINGLETON=1 to skip the reap (duplicate\ndelivery becomes possible). Safe to re-run on every restart (e.g. from a SessionStart hook), so a single\n'Monitor({ command: \"parlay listen --agent <id>\", persistent: true })' call is the whole enrollment.",
	"stats":         "parlay stats — message memory and complexity snapshot from the server.\nFetches up to 2000 messages and reports: count, total estimated size, avg/largest message, user vs agent split, image attachments, action cards, oldest/newest timestamps.\nPair with Ctrl+Shift+D in the panel for bundle load timing and live memory breakdown.",
	"health":        "parlay health — the SERVER's vitals in one glance.\nChecks: relay reachable (subscribers/pollers/agents counts + memory/history stats), the Pulse wrapper's\n/api/pulse/health when the relay runs inside Pulse, and the eval-engine /health (protocol version).\nExit 1 if the relay or engine is down. Same view for every caller — for YOUR OWN state, run: parlay doctor",
	"doctor":        "parlay doctor — THIS agent's self-diagnosis; every check prints PASS/WARN/FAIL plus the fix command.\nChecks: server URL source (env/config/default) → PARLAY_AGENT_ID set → server reachable → registered on\nthe relay → monitor listening (presence) → identity.md/scratchpad.md exist, identity frontmatter parses\nand matches the agent id (handoff pointer noted) → eval-engine reachable. Runs every check even after\nfailures. Exit 1 if anything FAILed.\nEnv: PARLAY_SERVER, PARLAY_AGENT_ID, PARLAY_AGENT_HOME, PARLAY_EVAL_ENGINE_URL, PARLAY_STATE_HOME.\nSee 'parlay remote --help' for the persisted server-URL config.",
	"launch":        "parlay launch — discover and launch agents defined in ~/.parlay/agents/.\nUsage: parlay launch          → list all known agents with live status\n       parlay launch <id>    → spawn the named agent via parlay-spawn (reads identity.md for name/color/cwd/model)\nOffline agents are clearly marked; spawning fires the standard identity→handoff→scratchpad recovery chain.",
	"claim":         "parlay claim — one-call agent bootstrap (idea-tm0): profile + enrollment + the task, from a ticket.\nUsage: parlay claim <task-id> [--agent <id>] [--name <name>] [--color <hex>] [--model <m>] [--no-register] [--allow-closed] [--silent]\nA freshly-launched agent runs this and follows its printed brief. In one call it:\n  1. Resolves its agent PROFILE (id/name/color/model): flags > env (PARLAY_AGENT_ID/_NAME/_COLOR/_MODEL) >\n     the ticket's own metadata (parlay_agent_id/parlay_name/parlay_color/parlay_model) > derived (color from id).\n  2. ENROLLS: registers with the chat server + announces the claim on its channel (tab goes live now), then\n     prints the ONE 'parlay listen' Monitor command to arm its persistent poll loop (a CLI can't arm a harness\n     Monitor itself). --no-register skips the synchronous register/announce (still prints the brief);\n     --silent prints no arm-command and no Monitor{} instructions at all, for scripted/headless/batch\n     claims with no harness to arm one in — it still registers and announces, and the brief says plainly\n     that nothing is listening on the channel.\n  3. Resolves the TASK: <task-id> against the beads/robots federation (task-/robots-/idea-…), printing the\n     ticket's title + description as the actual work — so the task prompt lives on the ticket, not the spawn prompt.\nTask-id resolution shells out to the store wrapper for the id's leading token (task/robots/idea/…), falling back\nto a bare 'bd' on PATH. Exit 2 if <task-id> or an agent id is missing.\nNO WORK behind the claim (the ticket doesn't resolve, or resolves already CLOSED) does none of the above:\n  it records 'failed' in the agent's status file, announces the failure on its channel, prints the exit\n  procedure (handoff create → 'identity --park', the shutdown that does NOT relaunch), and exits 1 — so the\n  agent ends instead of lingering on an empty pane (robots-4ek1). --allow-closed claims a closed ticket anyway.",
	"merge-gate":    "parlay merge-gate — the truthful \"is this PR actually safe to merge?\" check (robots-jap6).\nUsage: parlay merge-gate <pr> [--repo owner/name] [--json]\nA green status check is NOT evidence that anything reviewed the code. CodeRabbit reports a check\nCONCLUSION of 'pass' even when it never ran (account-wide review rate limit) — only the free-text\ndescription says so — and it reports success regardless of how many findings it posted. An agent\nfollowing 'merge when all required checks are green' therefore auto-merges unreviewed code.\nThis verb refuses to treat the check conclusion as the merge signal. It asserts, in order:\n  1. PR is OPEN and not CONFLICTING\n  2. at least one check exists; none failing, none pending\n  3. no VACUOUS pass — green conclusion whose description admits it did not run\n  4. a review actually happened — a human review, or a CodeRabbit comment carrying a real-review\n     marker rather than the rate-limit template\n  5. that review covered the CURRENT head sha, not an older push\n  6. no review thread left unresolved\nExit codes: 0 ready (or already merged), 3 BLOCKED on the code (fix it on the branch), 5 PENDING (the\nreview is still running — nothing is known to be wrong yet), 6 INFRA (every red is a check that failed\nWITHOUT evaluating the diff — re-run the jobs), 4 NEEDS-DECISION (every blocker is the reviewer being\nunavailable — nothing on the branch changes it), 1 gh/network could not answer, 2 usage.\nFail-closed in every direction — a caller branching on non-zero refuses correctly. Class precedence is\ncode > pending > infra > reviewer-unavailable, so one real finding always keeps the whole verdict at 3.\nOn 6 (robots-6mw2), do NOT hunt a defect: a GitHub Actions job that dies in action setup ('Failed to\nresolve action download info' / 'Service Unavailable') reports bucket=fail with an EMPTY description,\nidentical to a real failure by status alone. The check run's ANNOTATIONS are the discriminator — a job\nthat ran the code always annotates 'Process completed with exit code N'. Re-run the failed jobs\n('gh run rerun <run-id> --failed --repo owner/name'), then re-run the gate; if a re-run dies the same\nway, that is a GitHub incident — signal needs-decision rather than re-running forever.\nOn 5, do NOT edit the branch (there is no defect yet, and a new push restarts the review in flight) and\ndo not merge — just re-run the gate once the check reports (robots-rwf8). Bound that wait: a check that\nnever finishes is a 4.\nOn 4, do not poll, do not edit the branch, and do not merge anyway: 'parlay status needs-decision' and\nlet the captain pick re-request / merge-and-disclose / park (robots-8kkq). An unbounded wait on a\nrate-limited reviewer is itself a defect — and waiting cannot work here, since CodeRabbit only reviews\non a new push or an explicit '@coderabbitai review' comment, never when the window lapses (robots-eowy).\nA refusal counts wherever it is written down: CodeRabbit edits its one comment in place, so after a\nlater push the refusal often exists ONLY in the check description. A vacuous check therefore reclassifies\n'stale-review' and 'no-review-evidence' to reviewer-unavailable exactly as a rate-limit comment does —\nthat pairing (vacuous-pass + stale-review) used to exit 3 and send a mechanic editing unobjected-to code.\nWhich repository (robots-g4qz): --repo wins; otherwise the `origin` remote; only with no usable origin\ndoes it fall back to gh's own pick. gh prefers a remote named `upstream` over `origin`, so in a FORK\nclone its pick is the parent project — a silent, well-formed verdict about a different repository's PR\nof the same number (worst case exit 0 'already MERGED' for a still-open, unreviewed fork PR). Every run\nprints the repo it answered about, and warns when GitHub answers for a different one.\nRun it before any merge: parlay merge-gate 45 || echo REFUSING",
	"branch-audit":  "parlay branch-audit — what does this branch REALLY change? (robots-d988).\nUsage: parlay branch-audit [<branch>] [--base <ref>] [--repo <path>] [--json]\n`git diff origin/main <branch>` does not answer a question about the branch. Two-dot diff renders the\nSYMMETRIC difference between two tips, so every file that exists only on main comes back as a D\n(deleted) line and every line main gained since the branch was cut comes back as a `-`. A branch that\nis merely N commits behind therefore reads as having deleted work it never touched.\nObserved on ~/code/firstmate (robots-90i7): a 16-commits-behind branch reported 75 files / 2990\ndeletions and 4 files 'deleted' from two already-merged PRs. Its real contribution was 21 files, all\nadditions, 1214 insertions, ZERO deletions — and the false positive escalated to 'do NOT merge,\nconsider discarding the branch and redoing the work'.\nThis verb never diffs tip against tip. It reports, separately:\n  1. TRUE CONTRIBUTION — git diff <merge-base> <branch> (equivalently <base>...<branch>)\n  2. STALENESS — 'N commits behind' on its own line, as a fact, never as a deletion\n  3. MERGE STRIPS — for every merge in <base>..<branch>, a diff against its OWN parents; a file a\n     parent had ADDED that the merge dropped is a real strip, while a file that predates both sides is\n     a deliberate delete on one side and only a note\nExit codes: 0 nothing dropped merged work — INCLUDING a badly-behind branch, and including files the\nbranch's own commits delete (deleting a file is ordinary work); 3 STRIPPED, a merge dropped a file no\ncommit on the branch authored a delete for (fix it on the branch, usually by rebasing the real work off\nthe poisoned base); 1 git could not answer; 2 usage.\nOut of scope on purpose: line-level reverts inside a file a merge MODIFIED rather than deleted. That\nneeds semantic review, and claiming to catch it here would be the same overreach this verb removes.\nBefore ever reporting that a branch reverts merged work: parlay branch-audit <branch> || echo STRIPPED",
	"commands":      "parlay commands — what is parlay running right NOW.\nUsage: parlay commands [--all] [--watch] [--agent <id>] [--verb <verb>] [--json]\nReads the server's live-command registry: one record per invocation that reported itself, with its\nverb, agent, pid, age, and how it ended. The chat panel's live-commands view renders the SAME server\nstate, so the two surfaces cannot disagree.\n  --all      also show recently finished/failed/expired records, not just running ones\n  --watch    follow changes over the existing SSE stream (one connection, no polling)\n  --json     machine-readable; same field names the panel sees\n  --agent    only this agent's invocations       --verb   only this verb\nWHAT THIS CANNOT SEE (by design — a view that silently omitted half the fleet would be worse):\n  · only the Go CLI reports itself; shell wrappers (parlay-spawn, parlay-monitor.sh), the retired TS\n    CLI, and work the server originates on its own are NOT tracked\n  · `parlay commands` itself is excluded, so the observer never appears in its own output\n  · set PARLAY_COMMAND_REPORT=0 to opt an invocation out of reporting entirely\nWHAT IS NEVER RECORDED: flag VALUES, positional arguments, message bodies, paths, raw argv. Only the\nverb, the agent id, the pid, and flag NAMES travel — command lines routinely carry secrets.\nA command killed without reporting its end is reaped by the server after ~90s and shown as `expired`\n(outcome no-heartbeat), never left permanently `running`. See docs/live-commands.md.\nExit codes: 0 ok (including \"the server is too old to have a registry\" — reported, not fatal); 1\nserver/runtime error — the server is unreachable, or `--watch`'s event stream ended; 2 usage.",
	"landed":        "parlay landed — the truthful \"did this fix ACTUALLY land?\" proof (robots-0a77).\nUsage: parlay landed <pr> [--repo owner/name] [--branch <remote>/<branch>] [--json]\nThe mechanic contract's proof of landing used to be hand-run as `gh pr view <n> --json state,mergedAt`.\nA BARE gh command does not mean what it reads like: gh's base-repo resolution prefers a remote named\n`upstream` over `origin`, so in a fork clone — which is every clone the fleet works in — it answers about\nthe PARENT project's PR of the same number. Observed live: state=MERGED, mergedAt months earlier, for a\nstranger's PR, while the real PR was still OPEN. That is a false FIXED claim produced by the very command\nthe guardrail prescribed.\nThis verb resolves the repository the way merge-gate does (--repo wins; else the `origin` remote; gh's own\npick only with no usable origin) and asserts BOTH halves of the proof together:\n  1. a git remote in THIS checkout points at the repository being asked about — otherwise the git half and\n     the gh half describe different repositories, which is the defect itself\n  2. GitHub answered about that same repository (not a same-numbered PR elsewhere)\n  3. the PR state is MERGED\n  4. the commit it produced is reachable from the remote base branch — `git branch -r --contains`, run\n     against the resolved remote rather than a hardcoded origin/main\nNeither half alone is enough: (3) alone is the fork defect above, and (4) alone cannot tell a merged PR\nfrom a commit pushed straight to main. Containment is checked for the MERGE commit, not the head sha, so\na squash or rebase merge is proven correctly; the remote is fetched once if the commit is not local yet.\nExit codes: 0 LANDED, 3 NOT-LANDED (the proof ran and failed — do not claim FIXED), 1 gh/git could not\nanswer, 2 usage. Fail-closed in every direction.\nRun it before any FIXED claim: parlay landed 45 || echo NOT-LANDED",
	"variant":       "parlay variant — manage variant agents (isolated git-worktree forks of an existing agent).\nSubcommands:\n  launch <primary-id> [--label <suffix>] [--model MODEL]\n      Fork a primary into a new variant. Creates a git worktree at ~/.parlay/worktrees/<variant-id>.\n      Label defaults to wt1, wt2, … (auto-incremented). Variant id: <primary>-<label>.\n  list [<primary-id>]\n      List all variants, optionally filtered to a specific primary.\n  merge <variant-id>\n      Append novel identity facts + scratchpad notes from the variant into the primary.\n      Deduplicated by content; merged lines tagged [from: <variant-id>]. Idempotent.\n  teardown <variant-id> [--force]\n      Merge insights (unless --force), remove the git worktree, unregister from Parlay,\n      and delete the variant home. Refuses if unmerged insights exist unless --force.",
	"crew-state":    "parlay crew-state — reconcile an agent's keyed status line against parlay's oracle (fold §3.6 Slice 3).\nUsage: parlay crew-state <id>\n  Outputs: <state> · source: <src> · <detail>\n  States: working, done, blocked, needs-decision, paused, failed, resolved, captain-held, unknown.\n  Sources: status (relay confirmed enrollment) | status-degraded (relay unreachable; may be stale)\n           | status-unenrolled (relay does not list the agent) | none (nothing on disk).\n  The on-disk status file always wins over 'unknown': a stale-but-valid state is never discarded,\n  and a FAILED relay lookup is never reported as 'not registered'.\n  Exit codes: 0 state determined; 3 enrolled but no status yet; 4 relay does not list the agent;\n              5 status present but unreadable/unparseable; 6 relay unreachable and no status to fall back on.",
	"supervise":     "parlay supervise — wake-on-actionable-status loop with absorb-when-working logic (fold §3.6 Slice 3).\n  Routine verbs (working, paused, resolved, captain-held) are absorbed and only wake if a wedge is detected.\n  Env: PARLAY_UNATTENDED_FLAG — when set to a file path that exists, supervise runs in unattended\n  (away) mode: buffers escalations in a durable queue, detects captain return via in-band marker.",
	"sweep":         "parlay sweep — the fleet closure sweep (robots-6xq7): the collector that walks every\nparlay agent store, reads its crew-state, and tears down the ones that are provably finished.\n  Usage: parlay sweep [--apply] [--agent <id>] [--all] [--force] [--interval <sec>] [--verbose]\n  Default is a DRY RUN — it prints the plan and changes nothing.\n  --apply            Actually tear down (each via the same chain 'parlay teardown' runs).\n  --agent <id>       Sweep just this agent; substitutes for the per-task-spawn proof.\n  --all              Drop the per-task-spawn proof fleet-wide (still honors every safety hold).\n  --force            Also sweep agents with no launch spec on disk (implies --all). Their\n                     worktree, if any, is unrecorded and therefore unchecked by teardown —\n                     read the HOLD reason first.\n  --interval <sec>   Loop forever on this cadence (run it alongside robots-watch).\n  --verbose          Also print the quiet skips (agents that are simply still working).\n  Never swept: the sweeping agent itself; ids in $PARLAY_STATE_HOME/sweep-keep; anything in\n  needs-decision/blocked/failed (HELD for the captain — a teardown would destroy what he needs\n  to read). A done agent with uncommitted or unlanded work is refused by teardown, not forced.",
	"stale":         "parlay stale — the stale-window detector (robots-9d2w): is this pane worth SENDING to, or\nshould it be relaunched? A finished agent is still registered, still enrolled, and still accepts\nmessages — so a re-task lands in a session whose transcript is entirely the job it already closed,\nand every turn of the new work re-pays for it (the captain caught one at 70% context whose own\nharness was offering \"/clear to save 141.4k tokens\").\n  Usage: parlay stale <agent-id> [--quiet]\n  Exit 0 FRESH — continue it. Exit 3 STALE — relaunch instead. Exit 2 usage.\n  Exit 3 matches 'context-check' (ROTATE): the same call from the other side of the pane.\n  --quiet   exit code only, no output (for scripts).\nSTALE means a terminal status verb (done/failed) on an enrolled agent — it stopped and is sitting at\nits prompt. Deliberately NOT stale: needs-decision/blocked/paused (waiting on a reply — a message is\nthe intended unblock), working, and unknown (fail-open: a relay hiccup must never become a refused\nsend). Ids on $PARLAY_STATE_HOME/sweep-keep are never stale — that list is already sweep's escape\nhatch for long-lived agents that ARE re-tasked in place.\nRead-only: it never tears down, spawns, or sends. Closing a stale window is 'parlay sweep --apply'.\n'parlay send' runs this check itself and refuses a stale target; --force waives it.",
	"teardown":      "parlay teardown — safe destroy of an agent with an isolated worktree (fold §3.7 Slice 3).\n  Refuses to remove agents that have uncommitted changes or unpushed commits not yet landed.\n  Validates landed-content containment with one check: merge-tree tree-OID equality against the\n  default branch (catches squash-merged work). No PR/patch-id check exists — inconclusive means refuse.\n  Usage: parlay teardown <id> [--force]\n  --force   Override refusal and discard unlanded work.\n  Steps: (1) check git status, (2) validate unpushed commits are landed, (3) deregister from relay,\n  (4) remove worktree, (5) delete agent store.",
	"guard":         "parlay guard — runtime worktree-tangle + watcher-liveness alarm (ported from firstmate fm-guard.sh, AGENTS.md §8).\nParlay's isolation primitive is 'parlay variant' (a linked worktree at ~/.parlay/worktrees/<id>). The tangle failure\nmode is a parlay agent branching/committing in the PRIMARY checkout instead of its own variant worktree, stranding\nthe primary on a feature branch. This is the RUNTIME backstop for that — the brief/enrollment prose is only the\nupstream assertion. WARNS, never BLOCKS: always exits 0 (usage errors exit 2).\nUsage: parlay guard [--repo <path>] [--grace <sec>] [--read-only] [--json]\n       parlay guard --beat [--json]\n  --repo <path>   primary checkout to check (default: cwd's git toplevel)\n  --grace <sec>   watcher-liveness grace window (default 300)\n  --read-only     advisory phrasing — leave restore/repair to the session holding the fleet lock\n  --beat          touch the liveness beacon and exit (a live watcher/monitor calls this each poll cycle)\n  --json          machine-readable status\nChecks: (1) TANGLE — primary checkout on a NAMED non-default branch → bordered banner naming the branch + a\nnon-destructive 'git checkout <default>' restore (the branch ref is kept). Detached HEAD (linked worktrees) never\ntrips it. (2) LIVENESS — with variants in flight, a missing/stale beacon → 'WATCHER DOWN' banner.\nBeacon: $PARLAY_STATE_HOME/guard/.last-watcher-beat (default ~/.parlay/…).",
	"lavish-import": "parlay lavish-import — import lavish sessions via the bundled importer.\nUsage: parlay lavish-import",
	"context-check": "parlay context-check — machine-readable rotation advisory for persistent agents.\nUsage: parlay context-check <pct> [--threshold <pct>]\n  <pct>              your current context usage (0–100). Accepts 85, 85%, or 0.85. YOU pass what\n                     your harness knows — Claude Code exposes no context gauge to a CLI.\n  --threshold <pct>  rotate at/above this (default 85).\nOutput + exit codes (scriptable): below → 'OK <pct>% (threshold <t>%)', exit 0;\n  at/above → 'ROTATE: create handoff now, then identity --submit …', exit 3; bad pct → exit 2.\nRotation loop: on ROTATE, write a handoff then 'identity --submit' (atomic — see identity --help).\n  The supervisor-respawn side lives in GasCity. Example:\n    parlay context-check 87 || { handoff create … && identity --submit; }",
	"robots-watch":  "parlay robots-watch — MVP event poll-daemon (decision-4zr interim bridge).\nPolls each watched store's '<store> list --all --json', diffs a persisted per-bead status cursor, and routes each\n(store, status-change) through a handler table. Stands in for the not-yet-built beads EMIT hook (task-n1ao);\nswap the poll source for the ingest endpoint later and the router/handlers are unchanged.\nUsage: parlay robots-watch [--interval <sec>] [--once] [--verbose]\n  --interval <sec>  poll cadence (default 15; ignored with --once)\n  --once            single poll pass then exit (tests / cron)\n  --verbose         log every pass + routed event to stderr\nHandlers:\n  (a) robots bead CREATED          → mechanic-dispatch <id> (idempotent)\n  (b) request/question/task CLOSED → notify the requester channel from the bead's 'notify:<channel>' label\n                                      via 'parlay send --<channel>'\nState: $PARLAY_STATE_HOME/robots-watch/cursor.json (default ~/.parlay/…). First sighting of a store SEEDS its\ncursor and fires nothing; only transitions observed AFTER seeding fire handlers. Run under launchd for the daemon.",
	"robots-tail":   "parlay robots-tail — PUSH fast path (task-jif2): byte-offset tailer of the robots events stream → mechanic-dispatch.\nModeled on the server hook-tailer: every ~1s it reads only the bytes past a persisted offset in\n$ROBOTS_EVENTS_FILE (default ~/data/robots/events.jsonl, appended by the robots create-emit wrapper), parses each\nnew line for a robots bead id, and calls mechanic-dispatch <id> (idempotent) immediately — sub-~1s create→dispatch.\nUsage: parlay robots-tail [--once] [--verbose]\n  --once      one tail pass from the persisted offset, then exit (tests / cron)\n  --verbose   log skipped lines\nFirst-ever run starts at EOF (no history replay); the persisted offset ($PARLAY_STATE_HOME/robots-watch/tail-offset)\nresumes across restarts. The poll daemon 'robots-watch' stays the reconciler fallback for any missed emit;\nmechanic-dispatch idempotency makes a double-fire from both paths safe. Run both under launchd.",
	"mechanic":      "parlay mechanic — kill switch for the robots→mechanic auto-spawner.\nPause or resume automatic mechanic dispatch with one command — no launchd fiddling, no killing the tailer.\nUsage: parlay mechanic off            create the sentinel file; dispatch is silenced immediately\n       parlay mechanic on             remove the sentinel file; dispatch resumes for NEW beads\n       parlay mechanic status         print on|off, the reason, and the resolved sentinel path\nDisabled state = presence of $PARLAY_STATE_HOME/mechanic-dispatch.off (default ~/.parlay/mechanic-dispatch.off),\nOR env PARLAY_MECHANIC_DISPATCH=off. Both trigger paths (robots-tail PUSH and robots-watch POLL) respect the gate.\nPrecedence: PARLAY_MECHANIC_DISPATCH=off forces off (wins over a missing sentinel);\nPARLAY_MECHANIC_DISPATCH=on does NOT force-enable past a present sentinel — the sentinel is the\ndurable operator intent and wins. When OFF, the tailer and poller continue running and advancing\ntheir offsets normally; only the spawn is skipped, so re-enabling does NOT replay the backlog.",
}

// Lookup returns the help text for cmd, or ok=false if there is none registered.
func Lookup(cmd string) (string, bool) {
	t, ok := HELP[cmd]
	return t, ok
}

// Wanted checks argv for --help/-h; if present, prints cmd's help text (or
// the full USAGE if cmd has none registered) and returns true — matching
// help.ts's helpWanted(). Callers return immediately when this is true.
func Wanted(cmd string, argv []string) bool {
	asked := false
	for _, a := range argv {
		if a == "--help" || a == "-h" {
			asked = true
			break
		}
	}
	if !asked {
		return false
	}
	if text, ok := HELP[cmd]; ok {
		fmt.Println(text)
	} else {
		fmt.Println(Usage(config.ServerURL()))
	}
	return true
}
